    @Test
    public void chief_ray_aiming() {
        var fields = build().optical_spec.fov.fields;
        Assertions.assertNotNull(fields[0].aim_info, "aim.0.x - expected paraxial aiming");
        assertClose("aim.0.x", 0.0d, fields[0].aim_info[0], 1.0e-6);
        Assertions.assertNotNull(fields[0].aim_info, "aim.0.y - expected paraxial aiming");
        assertClose("aim.0.y", 0.0d, fields[0].aim_info[1], 1.0e-6);
        Assertions.assertNotNull(fields[1].aim_info, "aim.1.x - expected paraxial aiming");
        assertClose("aim.1.x", 0.0d, fields[1].aim_info[0], 1.0e-6);
        Assertions.assertNotNull(fields[1].aim_info, "aim.1.y - expected paraxial aiming");
        assertClose("aim.1.y", -1.976869320154433d, fields[1].aim_info[1], 1.0e-6);
        Assertions.assertNotNull(fields[2].aim_info, "aim.2.x - expected paraxial aiming");
        assertClose("aim.2.x", 0.0d, fields[2].aim_info[0], 1.0e-6);
        Assertions.assertNotNull(fields[2].aim_info, "aim.2.y - expected paraxial aiming");
        assertClose("aim.2.y", -4.0525031439067805d, fields[2].aim_info[1], 1.0e-6);
    }

