        assertClose("ray.1.0.1.dst", 4.851208678497147d, s1.dst, 1.0e-6);
        var s2 = pkg.ray.get(2);
        assertClose("ray.1.0.2.p.x", 0.0d, s2.p.x, 1.0e-6);
        assertClose("ray.1.0.2.p.y", -9.824936584584016d, s2.p.y, 1.0e-6);
