        assertClose("ray.2.2.1.dst", 3.8922189811872485d, s1.dst, 1.0e-6);
        var s2 = pkg.ray.get(2);
        assertClose("ray.2.2.2.p.x", 13.973636668554482d, s2.p.x, 1.0e-6);
        assertClose("ray.2.2.2.p.y", -15.23962035337424d, s2.p.y, 1.0e-6);
